import SVGPathCommander from "svg-path-commander";
function sampleCurveSegment(segmentPath, samplesPerUnit) {
  const commander = new SVGPathCommander(segmentPath);
  const length9 = commander.getTotalLength();
  const numSamples = Math.max(2, Math.ceil(length9 * samplesPerUnit));
  const points = [];
  for (let i2 = 1; i2 <= numSamples; i2++) {
    const t48 = i2 / numSamples * length9;
    const point7 = commander.getPointAtLength(t48);
    points.push({ x: point7.x, y: point7.y });
  }
  return points;
}
function svgPathToPoints(svgPath, samplesPerUnit = 10) {
  const pathCommander = new SVGPathCommander(svgPath);
  pathCommander.toAbsolute();
  const segments = pathCommander.segments;
  const result = [];
  let currentPoints = [];
  let currentX = 0;
  let currentY = 0;
  let subpathStartX = 0;
  let subpathStartY = 0;
  for (const segment4 of segments) {
    const cmd = segment4[0];
    switch (cmd) {
      case "M": {
        if (currentPoints.length > 0) {
          result.push(currentPoints);
        }
        currentX = segment4[1];
        currentY = segment4[2];
        subpathStartX = currentX;
        subpathStartY = currentY;
        currentPoints = [{ x: currentX, y: currentY }];
        break;
      }
      case "L": {
        currentX = segment4[1];
        currentY = segment4[2];
        currentPoints.push({ x: currentX, y: currentY });
        break;
      }
      case "H": {
        currentX = segment4[1];
        currentPoints.push({ x: currentX, y: currentY });
        break;
      }
      case "V": {
        currentY = segment4[1];
        currentPoints.push({ x: currentX, y: currentY });
        break;
      }
      case "Z": {
        if (currentX !== subpathStartX || currentY !== subpathStartY) {
          currentPoints.push({ x: subpathStartX, y: subpathStartY });
        }
        currentX = subpathStartX;
        currentY = subpathStartY;
        break;
      }
      case "C": {
        const endX = segment4[5];
        const endY = segment4[6];
        const segmentPath = `M ${currentX} ${currentY} C ${segment4[1]} ${segment4[2]} ${segment4[3]} ${segment4[4]} ${endX} ${endY}`;
        const sampledPoints = sampleCurveSegment(segmentPath, samplesPerUnit);
        currentPoints.push(...sampledPoints);
        currentX = endX;
        currentY = endY;
        break;
      }
      case "S": {
        const endX = segment4[3];
        const endY = segment4[4];
        const segmentPath = `M ${currentX} ${currentY} S ${segment4[1]} ${segment4[2]} ${endX} ${endY}`;
        const sampledPoints = sampleCurveSegment(segmentPath, samplesPerUnit);
        currentPoints.push(...sampledPoints);
        currentX = endX;
        currentY = endY;
        break;
      }
      case "Q": {
        const endX = segment4[3];
        const endY = segment4[4];
        const segmentPath = `M ${currentX} ${currentY} Q ${segment4[1]} ${segment4[2]} ${endX} ${endY}`;
        const sampledPoints = sampleCurveSegment(segmentPath, samplesPerUnit);
        currentPoints.push(...sampledPoints);
        currentX = endX;
        currentY = endY;
        break;
      }
      case "T": {
        const endX = segment4[1];
        const endY = segment4[2];
        const segmentPath = `M ${currentX} ${currentY} T ${endX} ${endY}`;
        const sampledPoints = sampleCurveSegment(segmentPath, samplesPerUnit);
        currentPoints.push(...sampledPoints);
        currentX = endX;
        currentY = endY;
        break;
      }
      case "A": {
        const endX = segment4[6];
        const endY = segment4[7];
        const segmentPath = `M ${currentX} ${currentY} A ${segment4[1]} ${segment4[2]} ${segment4[3]} ${segment4[4]} ${segment4[5]} ${endX} ${endY}`;
        const sampledPoints = sampleCurveSegment(segmentPath, samplesPerUnit);
        currentPoints.push(...sampledPoints);
        currentX = endX;
        currentY = endY;
        break;
      }
    }
  }
  if (currentPoints.length > 0) {
    result.push(currentPoints);
  }
  return result.map((points) => {
    const deduped = [];
    for (const point7 of points) {
      if (deduped.length === 0 || Math.abs(deduped[deduped.length - 1].x - point7.x) > 1e-9 || Math.abs(deduped[deduped.length - 1].y - point7.y) > 1e-9) {
        deduped.push(point7);
      }
    }
    return deduped;
  });
}

